create extension if not exists pgcrypto;
create table if not exists public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,role text not null default 'atlm' check(role in('admin','atlm','reviewer','viewer')),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.devices(id uuid primary key default gen_random_uuid(),device_code text unique not null,device_name text not null,firmware_version text,last_seen_at timestamptz,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.examinations(id uuid primary key default gen_random_uuid(),accession_code text unique not null,sample_code text not null,test_method text not null check(test_method in('slide','tube')),status text not null default 'draft' check(status in('draft','captured','analyzed','reviewed','finalized','cancelled')),device_id uuid references public.devices(id),created_by uuid not null references auth.users(id),original_image_path text,annotated_image_path text,image_sha256 text,captured_at timestamptz,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.analysis_runs(id uuid primary key default gen_random_uuid(),examination_id uuid not null references public.examinations(id) on delete cascade,algorithm_name text not null,algorithm_version text not null,qc_status text not null check(qc_status in('pass','review_required','fail')),pattern_class text not null check(pattern_class in('no_visible_agglutination','visible_agglutination','uncertain')),confidence numeric(5,4) check(confidence between 0 and 1),feature_summary jsonb,processing_ms integer,created_at timestamptz not null default now());
create table if not exists public.reaction_readings(id uuid primary key default gen_random_uuid(),examination_id uuid not null references public.examinations(id) on delete cascade,antigen_code text not null,ai_observation text,atlm_observation text,titer_text text,verified_by uuid references auth.users(id),verified_at timestamptz,created_at timestamptz not null default now(),unique(examination_id,antigen_code));
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),examination_id uuid references public.examinations(id),action text not null,details jsonb,created_at timestamptz not null default now());
create index if not exists idx_examinations_created on public.examinations(created_at desc);
create index if not exists idx_examinations_status on public.examinations(status);
create index if not exists idx_analysis_exam on public.analysis_runs(examination_id);
create index if not exists idx_readings_exam on public.reaction_readings(examination_id);
create or replace function public.current_app_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where user_id=auth.uid() and is_active=true $$;
alter table public.profiles enable row level security; alter table public.devices enable row level security; alter table public.examinations enable row level security; alter table public.analysis_runs enable row level security; alter table public.reaction_readings enable row level security; alter table public.audit_logs enable row level security;
create policy "profiles_select_own_or_admin" on public.profiles for select to authenticated using(user_id=auth.uid() or public.current_app_role()='admin');
create policy "devices_select_authenticated" on public.devices for select to authenticated using(true);
create policy "devices_admin_all" on public.devices for all to authenticated using(public.current_app_role()='admin') with check(public.current_app_role()='admin');
create policy "examinations_select_authenticated" on public.examinations for select to authenticated using(true);
create policy "examinations_insert_staff" on public.examinations for insert to authenticated with check(created_by=auth.uid() and public.current_app_role() in('admin','atlm'));
create policy "examinations_update_reviewer" on public.examinations for update to authenticated using(public.current_app_role() in('admin','atlm','reviewer')) with check(public.current_app_role() in('admin','atlm','reviewer'));
create policy "analysis_select_authenticated" on public.analysis_runs for select to authenticated using(true);
create policy "analysis_insert_staff" on public.analysis_runs for insert to authenticated with check(public.current_app_role() in('admin','atlm'));
create policy "readings_select_authenticated" on public.reaction_readings for select to authenticated using(true);
create policy "readings_insert_staff" on public.reaction_readings for insert to authenticated with check(public.current_app_role() in('admin','atlm','reviewer'));
create policy "readings_update_staff" on public.reaction_readings for update to authenticated using(public.current_app_role() in('admin','atlm','reviewer')) with check(public.current_app_role() in('admin','atlm','reviewer'));
create policy "audit_admin_read" on public.audit_logs for select to authenticated using(public.current_app_role()='admin');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('widal-images','widal-images',false,5242880,array['image/jpeg','image/png']) on conflict(id) do nothing;
create policy "widal_storage_read_own" on storage.objects for select to authenticated using(bucket_id='widal-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "widal_storage_insert_own" on storage.objects for insert to authenticated with check(bucket_id='widal-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "widal_storage_update_own" on storage.objects for update to authenticated using(bucket_id='widal-images' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='widal-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "widal_storage_delete_own" on storage.objects for delete to authenticated using(bucket_id='widal-images' and (storage.foldername(name))[1]=auth.uid()::text);